INSERT INTO categorias (nome) SELECT 'Tecnologia' WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE nome = 'Tecnologia');
INSERT INTO categorias (nome) SELECT 'Dados' WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE nome = 'Dados');
INSERT INTO categorias (nome) SELECT 'Negócios' WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE nome = 'Negócios');
INSERT INTO categorias (nome) SELECT 'Segurança' WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE nome = 'Segurança');
INSERT INTO categorias (nome) SELECT 'Produtividade' WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE nome = 'Produtividade');
INSERT INTO cursos (titulo, descricao, categoria_id, nivel, duracao_minutos, icone, destaque, ordem_exibicao) SELECT 'Cloud Computing Essencial', 'Entenda os conceitos de cloud, serviços e modelos de implantação.', c.id, 'Iniciante', 300, 'cloud', 0, 1 FROM categorias c WHERE c.nome = 'Tecnologia' AND NOT EXISTS (SELECT 1 FROM cursos WHERE titulo = 'Cloud Computing Essencial') ORDER BY c.id LIMIT 1;
